"use client";

import { useEffect, useState } from "react";
import { useRouter, useSearchParams } from "next/navigation";
import { Loader2 } from "lucide-react";

export default function AuthProvider({ children }: { children: React.ReactNode }) {
    const router = useRouter();
    const searchParams = useSearchParams();
    const [authorized, setAuthorized] = useState(false);

    useEffect(() => {
        const urlToken = searchParams.get("token");
        const storedToken = localStorage.getItem("auth_token");

        if (urlToken) {
            // New session from WhatsApp link
            localStorage.setItem("auth_token", urlToken);
            setAuthorized(true);
            // Clean URL
            router.replace("/");
        } else if (storedToken) {
            // Existing session
            setAuthorized(true);
        } else {
            // No token found
            setAuthorized(false);
        }
    }, [router, searchParams]);

    if (!authorized) {
        return (
            <div className="flex flex-col items-center justify-center min-h-screen bg-background p-6 text-center">
                <div className="w-16 h-16 bg-primary/10 rounded-full flex items-center justify-center mb-6 animate-pulse">
                    <Loader2 className="text-primary animate-spin" size={32} />
                </div>
                <h1 className="text-2xl font-bold mb-2">Verifying Access...</h1>
                <p className="text-muted-foreground max-w-xs">
                    Please use the link sent to your WhatsApp to access the menu.
                </p>
            </div>
        );
    }

    return <>{children}</>;
}

from datetime import datetime, timedelta
from typing import Optional
from jose import jwt, JWTError
from ..config import settings

class AuthService:
    """Service for handling authentication and token management"""

    SECRET_KEY = settings.api_key  # Using API_KEY as secret for simplicity, or add a new env var
    ALGORITHM = "HS256"
    ACCESS_TOKEN_EXPIRE_MINUTES = 60 * 24  # 24 hours

    @classmethod
    def create_access_token(cls, data: dict, expires_delta: Optional[timedelta] = None) -> str:
        """Generate a JWT access token"""
        to_encode = data.copy()
        if expires_delta:
            expire = datetime.utcnow() + expires_delta
        else:
            expire = datetime.utcnow() + timedelta(minutes=cls.ACCESS_TOKEN_EXPIRE_MINUTES)

        to_encode.update({"exp": expire})
        encoded_jwt = jwt.encode(to_encode, cls.SECRET_KEY, algorithm=cls.ALGORITHM)
        return encoded_jwt

    @classmethod
    def verify_token(cls, token: str) -> Optional[dict]:
        """Verify and decode a JWT token"""
        try:
            payload = jwt.decode(token, cls.SECRET_KEY, algorithms=[cls.ALGORITHM])
            return payload
        except JWTError:
            return None

auth_service = AuthService()

import axios from 'axios';

// Create axios instance with base URL
const api = axios.create({
    baseURL: process.env.NEXT_PUBLIC_API_URL || 'http://localhost:8000',
